import { PrismaClient } from '@prisma/client'
import 'dotenv/config'

async function setupDb() {


  const dbUrl = process.env.DATABASE_URL ?? 'postgres://postgres:postgrespw@localhost:5432/ffy_dev'


  const url = new URL(dbUrl)
  url.pathname = '/postgres' 
  url.port = '5432' 
  const postgresUrl = url.toString()

  const db = new PrismaClient({
    datasources: {
      db: {
        url: postgresUrl,
      },
    },
  })

  async function checkAndCreateDatabase(dbName: string) {
    try {

      const result: Array<{ datname: string }> = await db.$queryRaw`
        SELECT datname FROM pg_database WHERE datname = ${dbName}
      `


      if (result.length === 0) {
        await db.$executeRawUnsafe(`CREATE DATABASE ${dbName}`)
        console.log(`Database ${dbName} created successfully.`)
      }
    } catch (e) {
      if (!e.message.includes(`database "${dbName}" already exists`)) {
        console.log(`Error with database ${dbName}:`, e)
      }
    }
  }


  console.log('Checking existence of Postgres databases for development.')
  await checkAndCreateDatabase('ffy_dev')
  await checkAndCreateDatabase('ffy_shadow')
  await checkAndCreateDatabase('ffy_test')

  console.log(
    'For development, if you haven´t done it already, please add the following entries to your .env file and edit them properly:',
  )
  console.log('')
  console.log('DATABASE_URL=postgres://postgres:posgrespw@localhost:5432/ffy_dev')
  console.log('TEST_DATABASE_URL=postgres://postgres:posgrespw@localhost:5432/ffy_test')
  console.log('SHADOW_DATABASE_URL=postgres://postgres:posgrespw@localhost:5432/ffy_shadow')
  console.log('VALKEY_PERSISTENT_SERVER=localhost  # Valkey for BullMQ (noeviction)')
  console.log('VALKEY_PERSISTENT_PORT=6380')
  console.log('VALKEY_SERVER=localhost             # Valkey for PubSub/Caching (LRU)')
  console.log('VALKEY_PORT=6379')
  console.log('✅ DB successfully set up!')
  await db.$disconnect()
}

