import type { FastifyPluginAsyncTypebox } from '@fastify/type-provider-typebox'
import { Type } from '@sinclair/typebox'

const plugin: FastifyPluginAsyncTypebox = async (fastify) => {
  fastify.post(
    '/login',
    {
      preValidation: fastify.passport.authenticate(['local'], {
        successMessage: 'Successfully logged in.',
        failureMessage: 'Log in failed',
      }),
      schema: {
        body: Type.Object({
          password: Type.String(),
          email: Type.String({ format: 'email' }),
        }),
        response: {
          200: Type.Object({
            success: Type.Boolean(),
            message: Type.Optional(Type.String()),
          }),
          401: Type.Object({
            message: Type.String(),
          }),
        },
        tags: ['Authentication'],
      },
    },
    async (request, reply) => {
      if (request.user) {
        request.session.set('loginProvider', 'local')


        reply.status(200).send({ success: true, message: 'Successfully logged in.' })
      } else {

        reply.status(401).send({ message: 'Not authorized.' })
      }
    },
  )
}

export default plugin

